DEFAULT_EXCLUDE = {
    ".venv/",
    "venv/",
    "__pycache__/",
    ".git/",
    ".github/",
    "build/",
    "dist/",
    ".pytest_cache/",
    ".ruff_cache/",
    ".mypy_cache/",
