}


class IgnoreMatcher:
    """Handles .analyzerignore patterns using fnmatch."""

    def __init__(self, root_path: pathlib.Path, patterns: List[str]):
        self.root_path = root_path
        # Combine user patterns with defaults
        all_patterns = set(
            p.strip() for p in patterns if p.strip() and not p.startswith("#")
        )
        all_patterns.update(DEFAULT_EXCLUDE)
        self.patterns = list(all_patterns)
        self._cache = {}

    def is_ignored(self, path: pathlib.Path) -> bool:
        """Returns True if the path matches any of the ignore patterns."""
        str_path = str(path)
        if str_path in self._cache:
            return self._cache[str_path]

        try:
            rel_path = path.relative_to(self.root_path)
            str_rel_path = str(rel_path)
            result = self._check_patterns(str_rel_path, path.name)
            self._cache[str_path] = result
            return result
        except ValueError:
            return False

    def _check_patterns(self, str_rel_path: str, name: str) -> bool:
        for pattern in self.patterns:
            # Handle anchored patterns (starting with /)
            is_anchored = pattern.startswith("/")
            clean_pattern = pattern.lstrip("/")

            # Handle directory-specific patterns (ending in /)
            is_dir_pattern = clean_pattern.endswith("/")
            clean_pattern = clean_pattern.rstrip("/")

            if is_dir_pattern:
                # If it's a directory pattern:
                # 1. it matches if str_rel_path is exactly the directory
                # 2. it matches if str_rel_path starts with directory + os.sep
                if is_anchored:
                    # Anchored: must be at the root of rel_path
                    if str_rel_path == clean_pattern or str_rel_path.startswith(
                        clean_pattern + os.sep
                    ):
                        return True
                else:
                    # Non-anchored: can be anywhere in rel_path
                    parts = str_rel_path.split(os.sep)
                    if clean_pattern in parts:
                        return True
            else:
                # Standard pattern (file or dir without trailing /)
                if is_anchored:
                    if fnmatch.fnmatch(str_rel_path, clean_pattern):
                        return True
                else:
                    # Match rel_path directly (glob)
                    if fnmatch.fnmatch(str_rel_path, clean_pattern):
                        return True
                    # Match basename (like gitignore for simple names)
                    if "/" not in clean_pattern and fnmatch.fnmatch(
                        name, clean_pattern
                    ):
                        return True
                    # Fallback for patterns that might be deep: check if any part of the path matches
                    # e.g. "docs/*.md" matching "src/docs/ref.md" -> not standard gitignore but common expectation
                    # Actually gitignore "docs/*.md" only matches root docs/*.md.
                    # But "**/docs/*.md" would match deep.
                    # Let's stick to standard fnmatch on rel_path first.
        return False


def load_ignore_patterns(ignore_file: pathlib.Path) -> List[str]:
    """Loads ignore patterns from a file."""
    if not ignore_file.exists():
        return []
    with open(ignore_file) as f:
        return f.readlines()


def load_profile_config(
    project_path: pathlib.Path, profile_name: str = "default"
) -> Dict[str, Any]:
    """Loads a specific profile configuration from pyproject.toml."""
    pyproject = project_path / "pyproject.toml"
    default_config = {
        "strict": False,
        "generate_html": True,
        "fail_on_error": False,
        "rules": {},
    }

    if not pyproject.exists():
        return default_config

    try:
        with open(pyproject, "rb") as f:
            if tomllib:
                data = tomllib.load(f)
            else:
                data = _minimal_toml_load(f)

        profiles = data.get("tool", {}).get("qgis-analyzer", {}).get("profiles", {})
        profile_data = profiles.get(profile_name)

        if not profile_data:
            if profile_name != "default":
                logger.warning(
                    f"Profile '{profile_name}' not found. Using default values."
                )
            return default_config

        # Extract rules configuration
        rules_config = profile_data.get("rules", {})

        return {
            **default_config,
            **profile_data,
            "rules": rules_config,
        }
    except Exception as e:
        logger.error(f"Error loading profile: {e}")
        return default_config
